import { createAsyncThunk, createSlice } from "@reduxjs/toolkit";
import stampDutyPaymentService from "../services/stampDutyPaymentService";
import { uniqBy } from "lodash";

const initialState = {
  stampDutyPayments: [],
  isError: false,
  isSuccess: false,
  isLoading: false,
  message: "",
  next_page_param: null,
  generalLedgerEnteriesSyncPost: [],
};

export const createStampDutyPayment = createAsyncThunk(
  "stampDutyPayment/createStampDutyPayment",
  async ({ body }, thunkAPI) => {
    try {
      return await stampDutyPaymentService.createStampDutyPayment(body);
    } catch (error) {
      const message =
        (error.response &&
          error.response.data &&
          error.response.data.message) ||
        error.message ||
        error.toString();
      return thunkAPI.rejectWithValue(message);
    }
  }
);

