import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import addressWardService from "../services/addressWardService";
import { uniqBy } from "lodash";

// import Cookies from "js-cookie";
const initialState = {
  addressWards: [],
  isError: false,
  isSuccess: false,
  isLoading: false,
  message: "",
  addressWardData: [],
  next_page_param: null,
  addressWardsForPermanentAddress: {
    addressWards: [],
    isError: false,
    isSuccess: false,
    isLoading: false,
    message: "",
  },
  addressWardsForParkingAddress: { // New state for Parking Address
    addressWards: [],
    isError: false,
    isSuccess: false,
    isLoading: false,
    message: "",
  },
};

// Create new Ward
export const createAddressWard = createAsyncThunk(
  "addressWards/create",
  async (addressWardData, thunkAPI) => {
    try {
      const token = thunkAPI.getState().auth.user.access_token;
      return await addressWardService.createAddressWard(addressWardData, token);
    } catch (error) {
      const message =
        (error.response &&
          error.response.data &&
          error.response.data.message) ||
        error.message ||
        error.toString();
      return thunkAPI.rejectWithValue(message);
    }
  }
);

// Get Address Ward
export const getAddressWards = createAsyncThunk(
  "addressWards",
  async (params = null, thunkAPI) => {
    try {
      const token = thunkAPI.getState().auth.user.access_token;
      return await addressWardService.getAddressWards(token, params);
    } catch (error) {
      const message =
        (error.response &&
          error.response.data &&
          error.response.data.message) ||
        error.message ||
        error.toString();
      return thunkAPI.rejectWithValue(message);
    }
  }
);

export const getAddressWardList = createAsyncThunk(
  "addressWards/list",
  async ({ params, url, firstFetch = true }, thunkAPI) => {
    try {
      const response = await addressWardService.getAddressWardList(params, url);

      const {
        metadata: { info },
      } = response;

      const remainingPages = Math.ceil(
        ((+info?.total || 0) - (+info?.offset || 0)) / +info?.limit || 10
      );

      const next_page_param =
        remainingPages >= 1
          ? {
            ...params,
            offset: (+info?.limit || 10) + (+info?.offset || 0),
          }
          : null;
      return {
        info: info,
        data: response.data,
        firstFetch,
        next_page_param,
      };
    } catch (error) {
      const message =
        (error.response &&
          error.response.data &&
          error.response.data.message) ||
        error.message ||
        error.toString();
      return thunkAPI.rejectWithValue(message);
    }
  }
);

