import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import addressDistrictService from "../services/addressDistrictService";
import { get } from "lodash";
// import Cookies from "js-cookie";
const initialState = {
  addressDistricts: [],
  isError: false,
  isSuccess: false,
  isLoading: false,
  message: "",
  addressDistrictsForPermanentAddress: {
    addressDistricts: [],
    isError: false,
    isSuccess: false,
    isLoading: false,
    message: "",
  },
  addressDistrictsForParkingAddress: {
    addressDistricts: [],
    isError: false,
    isSuccess: false,
    isLoading: false,
    message: "",
  },
};

// Create new District
export const createAddressDistrict = createAsyncThunk(
  "addressDistricts/create",
  async (addressDistrictData, thunkAPI) => {
    try {
      const token = thunkAPI.getState().auth.user.access_token;
      return await addressDistrictService.createAddressDistrict(
        addressDistrictData,
        token
      );
    } catch (error) {
      const message =
        (error.response &&
          error.response.data &&
          error.response.data.message) ||
        error.message ||
        error.toString();
      return thunkAPI.rejectWithValue(message);
    }
  }
);

